response.body:
{{#formatJson}}
{{val request.query.page or=1 assign='page'}}{{val request.query.pageSize or=10 assign='limit'}}
{
  "connections": [
    {{~#arrayJoin ',' data.items as |connection|~}}
    {{#assign 'departure'}}{{request.query.date}}T{{connection.departure_time}}:00Z{{/assign}}
    {{#assign 'durationOffset'}}{{connection.duration_minutes}} minutes{{/assign}}
    {
      "connectionId": "{{connection.connection_id}}",
      "from": { "stationCode": "{{connection.from_station_code}}", "scheduledDeparture": "{{departure}}" },
      "to": { "stationCode": "{{connection.to_station_code}}", "scheduledArrival": "{{date (parseDate departure) offset=durationOffset}}" },
      "operator": { "code": "{{connection.operator_code}}", "name": "{{connection.operator_name}}" },
      "fare": { "amount": {{connection.fare_amount}}, "currency": "{{connection.fare_currency}}" },
      "facilities": { "bicyclesAllowed": {{connection.bicycles_allowed}}, "dogsAllowed": {{connection.dogs_allowed}} }
    }{{/arrayJoin}}
  ],
  "page": {{page}},
  "pageSize": {{limit}}
}
{{/formatJson}}

